""" Bubble sort impl O(n^2)
    @param m: sort collection
    @return sorted(@m)
    """
def bubble_sort(m: Any) -> object {
    for i in range((len(m) - 1)) {
        for j in range((len(m) - i - 1)) {
            if (m[j] > m[(j + 1)]) {
                (m[j], m[(j + 1)]) = (m[(j + 1)], m[j]);
            }
        }
    }
    return m;
}

